argv:
$ErrorActionPreference='SilentlyContinue'
$repo='E:\work\video2-r25-local'
$procs=@()
Get-CimInstance Win32_Process -Filter "Name='node.exe'" | Where-Object {
  $_.CommandLine -like '*video2-r25-local*' -or $_.CommandLine -like '*test:r25*' -or $_.CommandLine -like '*node --test*'
} | ForEach-Object {
  $procs += [pscustomobject]@{pid=$_.ProcessId;cmd=$_.CommandLine}
}
[pscustomobject]@{
  head=if(Test-Path $repo){(git -C $repo rev-parse HEAD 2>$null | Select-Object -First 1)}else{$null}
  clean=if(Test-Path $repo){[string]::IsNullOrWhiteSpace(((git -C $repo status --porcelain 2>$null) -join ''))}else{$false}
  nodeModules=(Test-Path (Join-Path $repo 'node_modules'))
  packageLock=(Test-Path (Join-Path $repo 'package-lock.json'))
  processes=$procs
} | ConvertTo-Json -Depth 4 -Compress
